  ('zcrm_5797994000003784879', 'Bluprynt', 'Bluprynt', 'Lakshita Ganesh Kumar', 'Christopher Brummer', 'Developer of a regulatory compliance operating system designed to automate and enforce digital asset compliance across blockchain networks. The company''s platform offers issuer identity verification, machine-readable disclosure compilation, verifiable credential issuance, and deterministic runtime enforcement infrastructure, enabling regulators, financial institutions, and digital asset issuers to manage cross-jurisdictional requirements through credential-based verification rather than embedded smart contract logic.', 'HV STEM', 'SaaS', 'Spring 2026', NULL, 'Reached Out', 'Lakshita Ganesh Kumar', 'Source', NULL, NULL, NULL, '2026-03-03 14:51:48', '2026-03-03 14:51:48', NULL),
  ('zcrm_5797994000003785019', 'Bubble Robotics', 'Bubble Robotics', 'Sameul Alam', 'Jean Crosetti', 'Bubble Robotics, a company focused on building advanced underwater robots. Their mission is to create autonomous ocean robotics for scalable subsea data collection to improve offshore efficiency and marine resource stewardship. By combining advanced resident robotics, seamless autonomy, and AI-powered analytics, they aim to revolutionize oceanexploration and operations, making the oceans safer, smarter, and more sustainable.', 'HV Genesis', 'Sustainability', 'Spring 2026', NULL, 'Reached Out', 'Sam Alam', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', 'Sam Alam', '2026-03-01 17:59:36', '2026-03-20 20:46:34', '2026-03-20 20:46:34'),
  ('zcrm_5797994000003785054', 'Protein Evolution', 'Protein Evolution', 'Sameul Alam', 'Connor Lynn', 'Protein Evolution is a biotech company ushering in a new era of sustainable and circular plastics.', 'HV Genesis', 'Sustainability', 'Spring 2026', NULL, 'Reached Out', 'Sam Alam', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', 'Sam Alam', '2026-03-01 18:03:33', '2026-03-20 20:46:34', '2026-03-20 20:46:34'),
  ('zcrm_5797994000003785089', 'Outlines', 'Outlines', 'Sameul Alam', 'Luke Young', 'Outlines designs and manufactures home essentials. The company considers how basic products are made, used, and disposed of when designing new products. Outlines employs recycling specialists from the very beginning of the design process, enabling them to optimize their products for recycling.', 'HV Genesis', 'Sustainability', 'Spring 2026', NULL, 'Reached Out', 'Sam Alam', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', 'Sam Alam', '2026-03-01 18:12:00', '2026-03-20 20:46:34', '2026-03-20 20:46:34'),
  ('zcrm_5797994000003785124', 'Novocycle Technologies', 'Novocycle Technologies', 'Sameul Alam', 'Pablo Fellay', 'Novocycle Technologies provides sustainable lithium-ion battery recycling and creates a circular battery supply chain.', 'HV Genesis', 'Sustainability', 'Spring 2026', NULL, 'Reached Out', 'Sam Alam', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', 'Sam Alam', '2026-03-01 18:15:03', '2026-03-20 20:46:34', '2026-03-20 20:46:34'),
