  ('zcrm_5797994000003817215', 'Point One Navigation', 'Point One Navigation', 'Vitoria Lunardi De Castro', 'Tom Weeks', 'Developer of a location and mapping system designed to assist autonomous vehicles. The company''s system utilizes sensor fusion techniques and networks to inform the location of vehicles and offers tailored autonomous systems, including self-driving vehicles, commercial drones, and other robotic applications to integrate highly accurate location data into their products, enabling robotics firms, mapping providers, and autonomous vehicle builders to secure their cars, drones, package delivery robots, ships, and trains.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:07:27', '2026-03-12 05:37:21', '2026-03-12 05:37:21'),
  ('zcrm_5797994000003817241', 'MadCo3d', 'Madco3d', 'Vitoria Lunardi De Castro', 'Adam Kushner', 'Operator of a three-dimensional printed concrete technology company intended to develop robotic, autonomous printing systems. The company''s design and build services help solve the housing crisis, restore the coastal marine environment, redefine the construction paradigm, and automate commercial building and infrastructure construction, providing builders with a greener approach to building and living.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:11:46', '2026-03-12 05:40:06', '2026-03-12 05:40:06'),
  ('zcrm_5797994000003817272', 'Foxglove', 'Foxglove', 'Vitoria Lunardi De Castro', 'Adrian Macneil', 'Developer of visualization and debugging platform designed to accelerate robotics development. The company''s platform features interactive visualizations that overlay bounding boxes and classification labels to drill down into data, flexible data source support where it connects directly to a running ROS environment on the machine and inspects pre-recorded data, enabling users to share layouts with team members for rapid collaboration and inspect sensor inputs such as images, point clouds, and time-series data.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:15:54', '2026-03-10 05:15:54', NULL),
  ('zcrm_5797994000003817303', 'B Garage', 'B Garage', 'Vitoria Lunardi De Castro', 'Young Joon Kim Ph.D', 'Operator of an autonomous drone platform designed to offer visibility into warehouse inventories at costs lower than other alternatives. The company''s technology implements collision prevention and evasion technology using low-cost sensors and deep learning technology, whereas the platform uses computer vision to offer visibility into warehouse inventories, enabling clients to manage inventories at reduced prices.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:19:42', '2026-03-10 05:19:42', NULL),
  ('zcrm_5797994000003817329', 'Industrial Next', 'Industrial Next', 'Vitoria Lunardi De Castro', 'Allen Pan', 'Developer of AI-powered industrial automation systems designed for reshoring and modernizing electronics manufacturing processes. The company''s system integrates human-level AI with advanced robotics to enable sight and touch-based automation, supports deployment in a matter of days, and adapts flexibly to changes in parts and workflows, enabling manufacturing companies to reduce supply chain risk, mitigate labor shortages, and achieve cost-effective domestic production.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:28:08', '2026-03-12 05:43:19', '2026-03-12 05:43:19'),
  ('zcrm_5797994000003817355', 'Carbon Origins', 'Carbon Origins', 'Vitoria Lunardi De Castro', 'Amogha Srirangarajan', 'Developer of virtual reality telerobotics designed to solve the labor crisis by combining human expertise with technology. The company designs and manufactures robotic systems that work from home using their virtual reality headsets to control robots doing everyday jobs, offers sub-perception latency, immersive three sixty-degree videos, spatial audio, lidar, radar sensor overlay, and artificial intelligence cues, enabling skilled heavy equipment operators to remote control multiple machines using a hyper-immersive VR interface, assisted by AI co-pilots.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2026-03-10 05:31:53', '2026-03-10 05:31:53', NULL),
  ('zcrm_5797994000003817429', 'Zero', 'Burt', 'Aditya Raj', 'Bobby Zhong', 'Developer of an artificial intelligence training and deployment platform intended to help technical teams build custom and specialized models. The company offers review, data preparation, training, evaluate and deployment services, enabling customers to maintain their proprietary data and model weights while outperforming industry benchmarks through precision-engineered datasets and expert-led training processes.', 'HV STEM', 'SaaS', 'Spring 2026', NULL, 'Reached Out', 'Aditya Raj', 'Source', NULL, NULL, NULL, '2026-03-10 12:51:07', '2026-03-10 12:51:07', NULL),
  ('zcrm_5797994000003817455', 'Billow AI', 'Billow AI', 'Aditya Raj', 'Joanathan McIntosh', 'Developer of an AI-powered financial modeling and scenario analysis platform designed for biotech and life sciences financial workflows. The company''s platform integrates directly with spreadsheet editors to automate valuation modeling, clinical trial budgeting, forecasting, benchmarking, assumption updates, scenario testing, M&A and proxy statement analysis, formula auditing, and generation of structured financial outputs, enabling biotech and life sciences finance teams to streamline model upkeep, reduce manual work, and make decisions with greater consistency and clarity.', 'HV STEM', 'SaaS', 'Spring 2026', NULL, 'Reached Out', 'Aditya Raj', 'Source', NULL, NULL, NULL, '2026-03-10 13:01:05', '2026-03-10 13:01:05', NULL),
  ('zcrm_5797994000003817484', 'BiteZen', 'BiteZen', 'Amelia Chapin', 'Brock Predovich', 'Developer of an AI-powered oral health platform intended to detect and manage teeth grinding and jaw clenching. The company offers a smart oral sensor that fits into a mouthguard to capture real-time clenching and grinding forces, a connected mobile app that records episodes across day and night, dashboards that track frequency and duration, providing dentists, healthcare providers, wellness-focused individuals, and people experiencing bruxism with an at-home assessment, ongoing monitoring, and data that supports earlier diagnosis', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Have not Reached out', 'Amelia Chapin', 'Source', NULL, NULL, NULL, '2026-03-10 18:42:43', '2026-03-10 18:42:43', NULL),
  ('zcrm_5797994000003817510', 'Biolinco', 'Biolinco', 'Amelia Chapin', 'Kent Rapp', 'Developer a biopharmaceutical therapies platform designed to reduce the cost of biomanufacturing by increasing drug yields. The company''s platform strives to offer end-to-end CLD services with proprietary, state-of-the-art technology proven to find the best cell line for a given biomanufacturing process.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Have not Reached out', 'Amelia Chapin', 'Source', NULL, NULL, NULL, '2026-03-10 18:44:56', '2026-03-10 18:44:56', NULL),
