  ('zcrm_5797994000003828478', 'Munify', 'Munify', 'Soham Shah', 'Khalid Ashmawy', 'Provider of digital financial infrastructure intended for global money movement and account management. The company''s platform supports multi-currency accounts, virtual card issuance, real-time cross-border transfers, invoice generation, and programmable APIs for pay-ins and payouts, enabling individuals, freelancers, and businesses to manage international transactions securely, reduce transfer costs, maintain control over funds, and operate across borders with minimal friction.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Pitchbook', 'Reached Out', 'Soham Shah', 'Source', 'Financial Innovation', NULL, NULL, '2026-03-22 06:32:01', '2026-03-22 06:32:01', '2026-03-22 06:32:01'),
  ('zcrm_5797994000003828513', 'Avantos', 'Avantos', 'Soham Shah', 'Bassam Chaptini Ph.D', 'Developer of an AI-native operating system designed to connect client data, teams, and processes across the relationship lifecycle. The company offers a knowledge graph layered over existing systems, agent-based onboarding and servicing workflows, and a shared workspace, enabling financial institutions to manage client onboarding, servicing, and ongoing relationship activities within a unified environment.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Pitchbook', 'Reached Out', 'Soham Shah', 'Source', 'Financial Innovation', NULL, NULL, '2026-03-22 06:34:15', '2026-03-22 06:34:15', '2026-03-22 06:34:15'),
